-- Schema-only migration: NO SELECT/UPDATE of legacy subaccounts, charges or splits.
-- IDs remain TEXT generated by Prisma client, consistent with current schema.
CREATE TYPE "DoctorRegistrationStatus" AS ENUM ('DRAFT','PENDING_REVIEW','VERIFIED','REJECTED');
CREATE TYPE "DoctorLicenseVerification" AS ENUM ('PENDING','VERIFIED','REJECTED');
CREATE TYPE "DoctorFinancialLinkStatus" AS ENUM ('PENDING_REVIEW','VERIFIED','REJECTED');
CREATE TYPE "DoctorProvisioningStatus" AS ENUM ('AWAITING_MSGDESK','IN_PROGRESS','LINKED','BLOCKED','NEEDS_RECONCILIATION');
CREATE TYPE "DoctorOperationStatus" AS ENUM ('COMPLETED','PENDING','NEEDS_RECONCILIATION','FAILED');
CREATE TABLE "doctors" (
 "id" TEXT NOT NULL,
 "full_name" VARCHAR(200) NOT NULL,
 "cpf_normalized" VARCHAR(11),
 "rg" VARCHAR(30),
 "rg_issuer" VARCHAR(60),
 "rg_state" VARCHAR(2),
 "birth_date" DATE,
 "email" VARCHAR(254),
 "mobile_phone" VARCHAR(32),
 "postal_code" VARCHAR(8),
 "street" VARCHAR(200),
 "street_number" VARCHAR(30),
 "address_complement" VARCHAR(120),
 "neighborhood" VARCHAR(120),
 "city" VARCHAR(120),
 "state" VARCHAR(2),
 "country" VARCHAR(2) NOT NULL DEFAULT 'BR',
 "registration_status" "DoctorRegistrationStatus" NOT NULL DEFAULT 'DRAFT',
 "registration_notes" VARCHAR(500),
 "verified_at" TIMESTAMPTZ(6),
 "msgdesk_auth_user_id" UUID,
 "msgdesk_organization_id" UUID,
 "provisioning_status" "DoctorProvisioningStatus" NOT NULL DEFAULT 'AWAITING_MSGDESK',
 "access_active" BOOLEAN NOT NULL DEFAULT false,
 "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMPTZ(6) NOT NULL,
 CONSTRAINT "doctors_pkey" PRIMARY KEY ("id"),
 CONSTRAINT "doctors_cpf_format" CHECK ("cpf_normalized" IS NULL OR "cpf_normalized" ~ '^[0-9]{11}$'),
 CONSTRAINT "doctors_cep_format" CHECK ("postal_code" IS NULL OR "postal_code" ~ '^[0-9]{8}$')
);
CREATE UNIQUE INDEX "doctors_cpf_normalized_key" ON "doctors"("cpf_normalized");
CREATE UNIQUE INDEX "doctors_msgdesk_auth_user_id_key" ON "doctors"("msgdesk_auth_user_id");
CREATE INDEX "doctors_registration_status_idx" ON "doctors"("registration_status");
CREATE INDEX "doctors_full_name_idx" ON "doctors"("full_name");
CREATE INDEX "doctors_msgdesk_organization_id_idx" ON "doctors"("msgdesk_organization_id");
CREATE TABLE "doctor_licenses" (
 "id" TEXT NOT NULL,
 "doctor_id" TEXT NOT NULL,
 "crm_normalized" VARCHAR(20) NOT NULL,
 "state" VARCHAR(2) NOT NULL,
 "verification_status" "DoctorLicenseVerification" NOT NULL DEFAULT 'PENDING',
 "verified_at" TIMESTAMPTZ(6),
 "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMPTZ(6) NOT NULL,
 CONSTRAINT "doctor_licenses_pkey" PRIMARY KEY ("id"),
 CONSTRAINT "doctor_licenses_state_format" CHECK ("state" ~ '^[A-Z]{2}$'),
 CONSTRAINT "doctor_licenses_crm_format" CHECK ("crm_normalized" ~ '^[0-9]{1,20}$')
);
CREATE UNIQUE INDEX "doctor_licenses_crm_normalized_state_key" ON "doctor_licenses"("crm_normalized","state");
CREATE INDEX "doctor_licenses_doctor_id_idx" ON "doctor_licenses"("doctor_id");
ALTER TABLE "doctor_licenses" ADD CONSTRAINT "doctor_licenses_doctor_id_fkey" FOREIGN KEY ("doctor_id") REFERENCES "doctors"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "doctor_financial_links" (
 "id" TEXT NOT NULL,
 "doctor_id" TEXT NOT NULL,
 "subaccount_id" TEXT NOT NULL,
 "status" "DoctorFinancialLinkStatus" NOT NULL DEFAULT 'PENDING_REVIEW',
 "active" BOOLEAN NOT NULL DEFAULT true,
 "verified_at" TIMESTAMPTZ(6),
 "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "revoked_at" TIMESTAMPTZ(6),
 CONSTRAINT "doctor_financial_links_pkey" PRIMARY KEY ("id")
);
-- One ACTIVE financial connection per doctor, but multiple doctors MAY share a
-- legitimate clinic wallet. Historical inactive links are retained.
CREATE UNIQUE INDEX "doctor_financial_links_one_active_doctor" ON "doctor_financial_links"("doctor_id") WHERE "active" = true;
CREATE INDEX "doctor_financial_links_doctor_id_active_idx" ON "doctor_financial_links"("doctor_id","active");
CREATE INDEX "doctor_financial_links_subaccount_id_idx" ON "doctor_financial_links"("subaccount_id");
ALTER TABLE "doctor_financial_links" ADD CONSTRAINT "doctor_financial_links_doctor_id_fkey" FOREIGN KEY ("doctor_id") REFERENCES "doctors"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "doctor_financial_links" ADD CONSTRAINT "doctor_financial_links_subaccount_id_fkey" FOREIGN KEY ("subaccount_id") REFERENCES "subaccounts"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
CREATE TABLE "doctor_provisioning_operations" (
 "id" TEXT NOT NULL,
 "doctor_id" TEXT,
 "kind" VARCHAR(40) NOT NULL,
 "idempotency_key" VARCHAR(100) NOT NULL,
 "request_hash" VARCHAR(64) NOT NULL,
 "status" "DoctorOperationStatus" NOT NULL DEFAULT 'PENDING',
 "result_doctor_id" TEXT,
 "remote_account_id" VARCHAR(100),
 "safe_error_code" VARCHAR(80),
 "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 "updated_at" TIMESTAMPTZ(6) NOT NULL,
 CONSTRAINT "doctor_provisioning_operations_pkey" PRIMARY KEY ("id")
);
CREATE UNIQUE INDEX "doctor_provisioning_operations_idempotency_key_key" ON "doctor_provisioning_operations"("idempotency_key");
CREATE INDEX "doctor_provisioning_operations_doctor_id_status_idx" ON "doctor_provisioning_operations"("doctor_id","status");
ALTER TABLE "doctor_provisioning_operations" ADD CONSTRAINT "doctor_provisioning_operations_doctor_id_fkey" FOREIGN KEY ("doctor_id") REFERENCES "doctors"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
